import { createHash } from "node:crypto";
import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const expectedPackage = "tauri-plugin-updater";
const expectedVersion = "2.10.1";
const expectedArchiveSha256 = "806d9dac662c2e4594ff03c647a552f2c9bd544e7d0f683ec58f872f952ce4af";
const ignoredBuildPaths = [
  "Cargo.lock",
  "permissions/autogenerated/",
  "permissions/schemas/",
  "target/",
];

function ignored(relativePath) {
  return ignoredBuildPaths.some(
    (candidate) => relativePath === candidate.replace(/\/$/, "") || relativePath.startsWith(candidate),
  );
}

function collectFiles(directory, relativeDirectory = "") {
  return readdirSync(path.join(directory, relativeDirectory), { withFileTypes: true }).flatMap(
    (entry) => {
      const relativePath = path.posix.join(relativeDirectory, entry.name);
      if (ignored(relativePath)) return [];
      if (entry.isDirectory()) return collectFiles(directory, relativePath);
      if (entry.isFile()) return [relativePath];
      throw new Error(`vendored updater contains unsupported filesystem entry: ${relativePath}`);
    },
  );
}

function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}

export function validateVendorEvidence(evidence) {
  const errors = [];
  const requireValue = (condition, message) => {
    if (!condition) errors.push(message);
  };
  const { provenance } = evidence;

  requireValue(provenance.schemaVersion === 1, "vendored updater provenance schema must be 1");
  requireValue(provenance.package === expectedPackage, "vendored updater package identity mismatch");
  requireValue(provenance.version === expectedVersion, "vendored updater version mismatch");
  requireValue(
    provenance.archiveSha256 === expectedArchiveSha256,
    "vendored updater archive checksum mismatch",
  );

  requireValue(Array.isArray(provenance.sourceFiles), "vendored updater source file manifest missing");
  const sourceFiles = Array.isArray(provenance.sourceFiles) ? provenance.sourceFiles : [];
  const sourceFilePaths = sourceFiles.map(({ path: sourcePath }) => sourcePath);
  requireValue(
    new Set(sourceFilePaths).size === sourceFilePaths.length,
    "vendored updater source file manifest contains duplicate paths",
  );
  for (const { path: sourcePath, sha256: sourceSha256 } of sourceFiles) {
    const validPath =
      typeof sourcePath === "string" &&
      sourcePath.length > 0 &&
      !sourcePath.startsWith("/") &&
      !sourcePath.includes("\\") &&
      path.posix.normalize(sourcePath) === sourcePath &&
      sourcePath !== ".." &&
      !sourcePath.startsWith("../");
    requireValue(validPath, `vendored updater invalid source path: ${sourcePath}`);
    requireValue(
      typeof sourceSha256 === "string" && /^[a-f0-9]{64}$/.test(sourceSha256),
      `vendored updater invalid SHA-256: ${sourcePath}`,
    );
  }
  const expectedFiles = [...sourceFilePaths, "provenance.json"].sort();
  const actualFiles = [...evidence.actualFiles].sort();
  requireValue(
    JSON.stringify(actualFiles) === JSON.stringify(expectedFiles),
    `vendored updater file allowlist mismatch: expected ${expectedFiles.join(", ")}; found ${actualFiles.join(", ")}`,
  );
  for (const { path: relativePath, sha256: expectedHash } of sourceFiles) {
    requireValue(
      evidence.actualHashes[relativePath] === expectedHash,
      `vendored updater checksum mismatch: ${relativePath}`,
    );
  }

  requireValue(
    /^name = "tauri-plugin-updater"$/m.test(evidence.vendorManifest),
    "vendored updater Cargo package name mismatch",
  );
  requireValue(
    /^version = "2\.10\.1"$/m.test(evidence.vendorManifest),
    "vendored updater Cargo package version mismatch",
  );
  requireValue(
    /tauri-plugin-updater = \{ version = "=2\.10\.1", path = "vendor\/tauri-plugin-updater" \}/.test(
      evidence.rootManifest,
    ),
    "FitFreed must use the exact reviewed vendored updater path and version",
  );
  requireValue(
    /exclude = \["vendor\/tauri-plugin-updater"\]/.test(evidence.rootManifest),
    "vendored updater must remain outside the FitFreed workspace package set",
  );
  requireValue(
    evidence.updaterSource.includes("pub fn prepare_update("),
    "vendored updater is missing authenticated release preparation",
  );
  requireValue(
    evidence.updaterSource.includes("pub async fn download_with_expected_size"),
    "vendored updater is missing bounded package download",
  );
  requireValue(
    evidence.errorSource.includes("DownloadSizeMismatch"),
    "vendored updater is missing its bounded-download error",
  );
  requireValue(
    !evidence.frontendManifest.includes("@tauri-apps/plugin-updater"),
    "the updater must not be exposed through a frontend package",
  );

  if (errors.length > 0) throw new Error(errors.join("\n"));
  return {
    package: provenance.package,
    version: provenance.version,
    archiveSha256: provenance.archiveSha256,
    verifiedFiles: sourceFiles.length,
  };
}

export function inspectVendoredUpdater(repositoryRoot) {
  const vendorDirectory = path.join(
    repositoryRoot,
    "src-tauri",
    "vendor",
    "tauri-plugin-updater",
  );
  const provenance = JSON.parse(readFileSync(path.join(vendorDirectory, "provenance.json"), "utf8"));
  const actualFiles = collectFiles(vendorDirectory);
  const actualHashes = Object.fromEntries(
    actualFiles
      .filter((relativePath) => relativePath !== "provenance.json")
      .map((relativePath) => [
        relativePath,
        sha256(readFileSync(path.join(vendorDirectory, relativePath))),
      ]),
  );
  return validateVendorEvidence({
    provenance,
    actualFiles,
    actualHashes,
    vendorManifest: readFileSync(path.join(vendorDirectory, "Cargo.toml"), "utf8"),
    rootManifest: readFileSync(path.join(repositoryRoot, "src-tauri", "Cargo.toml"), "utf8"),
    updaterSource: readFileSync(path.join(vendorDirectory, "src", "updater.rs"), "utf8"),
    errorSource: readFileSync(path.join(vendorDirectory, "src", "error.rs"), "utf8"),
    frontendManifest: readFileSync(path.join(repositoryRoot, "package.json"), "utf8"),
  });
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
  process.stdout.write(`${JSON.stringify(inspectVendoredUpdater(repositoryRoot))}\n`);
}
